#!/bin/sh
# Generated by tools/gemm_remote_leg.sh (--payload mamba). RUNS ON THE POD.
set -u
ROOT=/root/mojolearn
OUT=/root/gemm_leg_out
mkdir -p "$OUT"
cd "$ROOT" || exit 9
{
  echo "vendor=amd"
  echo "payload=mamba"
  echo "commit=718495cda991d96d0346b18ad1ef1fadfc8bed14"
  echo "started=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
} > "$OUT/leg.txt"
uname -a > "$OUT/uname.txt" 2>&1
rocm-smi --showproductname > "$OUT/gpu.txt" 2>&1 || echo "no vendor smi tool answered" >> "$OUT/gpu.txt"
{ find . -name '*.mojo' -not -path './.pixi/*' -not -path './bench/results/*' \
    | LC_ALL=C sort | xargs shasum -a 256 2>/dev/null || \
  find . -name '*.mojo' -not -path './.pixi/*' -not -path './bench/results/*' \
    | LC_ALL=C sort | xargs sha256sum ; } \
  | { shasum -a 256 2>/dev/null || sha256sum ; } \
  | awk '{print $1}' > "$OUT/source_sha256.txt"
if [ ! -x "$HOME/.pixi/bin/pixi" ] && ! command -v pixi >/dev/null 2>&1; then
    curl -fsSL https://pixi.sh/install.sh | sh > "$OUT/pixi_install.log" 2>&1
fi
PATH="$HOME/.pixi/bin:$PATH"
export PATH
pixi install > "$OUT/pixi_env.log" 2>&1
echo "pixi_install_exit=$?" >> "$OUT/leg.txt"
# Both witnesses share one work deadline, preserving the fetch reserve.
# Refuse without timeout instead of silently running an unbounded payload.
work_started=$(date +%s)
if ! command -v timeout >/dev/null 2>&1; then
    echo "umap_identity_exit=127" >> "$OUT/leg.txt"
    echo "timeout is required for the guarded payload" > "$OUT/mamba_cert_console.log"
    cert_rc=127
else
    timeout -k 30 180 pixi run mojo run -D MOJOLEARN_NUMERIC_IDENTICAL=1 \
      -I . umap/checks/identity_check.mojo > "$OUT/umap.identity.log" 2>&1
    echo "umap_identity_exit=$?" >> "$OUT/leg.txt"
    work_remaining=$((1200 - $(date +%s) + work_started))
    if [ "$work_remaining" -gt 0 ]; then
        MOJOLEARN_COMMIT="718495cda991d96d0346b18ad1ef1fadfc8bed14" MOJOLEARN_MAMBA_CERT_OUT="$OUT/mamba-cert" \
          MOJOLEARN_MAMBA_CERT_VENDOR="amd" \
          timeout -k 30 "$work_remaining" pixi run mamba-backward-cert-amd \
          > "$OUT/mamba_cert_console.log" 2>&1
        cert_rc=$?
    else
        echo "shared work deadline expired" > "$OUT/mamba_cert_console.log"
        cert_rc=124
    fi
fi
echo "mamba_cert_exit=$cert_rc" >> "$OUT/leg.txt"
echo "finished=$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$OUT/leg.txt"
tail -40 "$OUT/mamba_cert_console.log"
: > /root/gemm_leg.done
echo REMOTE_BODY_DONE
